data.activityservice#ActivityService:
See Agent activity.
Method Request → Response Notes SubscribeAgentActivity SubscribeAgentActivityRequest → stream SubscribeAgentActivityResponse Replays in-flight runs, then snapshot_complete, then live events. Scoped to session, or to the caller’s x-agent-trace-id. ListFeaturedMessages ListFeaturedMessagesRequest → ListFeaturedMessagesResponse An empty list is a success A client must render nothing for an unknown non-empty AgentStep.code, never the raw token.
message SubscribeAgentActivityRequest { int32 replay_steps_per_run = 1; string session = 2; } enum AgentRunStatus { AGENT_RUN_STATUS_UNSPECIFIED = 0; AGENT_RUN_STATUS_RUNNING = 1; AGENT_RUN_STATUS_DONE = 2; AGENT_RUN_STATUS_FAILED = 3; } message AgentRun { string run_id = 1; string agent = 2; string session = 3; int64 started_unix = 4; int64 ended_unix = 5; AgentRunStatus status = 6; int32 step_count = 7; repeated AgentStep steps = 8; string error = 9; } message AgentStep { string run_id = 1; int32 index = 2; string thought = 3; string action = 4; string input = 5; string result = 6; string model = 7; int64 latency_ms = 8; string error = 9; int64 at_unix = 10; int64 total_tokens = 11; string code = 12; map<string, string> operands = 13; StepProvenance provenance = 14; } message StepProvenance { string source = 1; string path = 2; bool degraded = 3; int64 computed_at_unix = 4; } message SubscribeAgentActivityResponse { oneof event { AgentRun snapshot = 1; bool snapshot_complete = 2; AgentRun run_started = 3; AgentStep step = 4; AgentRun run_finished = 5; } } message ListFeaturedMessagesRequest {} message FeaturedMessage { string id = 1; string title = 2; string body = 3; string locale = 4; string href = 5; string icon = 6; } message FeaturedMessage { string id = 1; string title = 2; string body = 3; string locale = 4; string href = 5; string icon = 6; } message ListFeaturedMessagesResponse { repeated FeaturedMessage messages = 1; string source = 2; }

data:
Shared messages and enums from commons.proto, used across the services.
Runner, Connection, and ActionCard are also defined there, but no PULSE service method takes or returns them.
message User { string id = 1; string email = 2; string display_name = 3; string avatar_url = 4; string role = 5; // "admin", "editor", "viewer" google.protobuf.Timestamp created_at = 6; google.protobuf.Timestamp updated_at = 7; } message PaginationRequest { int32 page = 1; int32 page_size = 2; string order_by = 3; // e.g. "created_at desc" string filter = 4; // free-form filter expression } message PaginationResponse { int32 total_count = 1; int32 page = 2; int32 page_size = 3; int32 total_pages = 4; } enum Channel { CHANNEL_UNSPECIFIED = 0; CHANNEL_LINKEDIN = 1; CHANNEL_INSTAGRAM = 2; CHANNEL_TIKTOK = 3; CHANNEL_BLOG = 4; CHANNEL_EMAIL = 5; CHANNEL_TWITTER = 6; CHANNEL_YOUTUBE = 7; CHANNEL_FACEBOOK = 8; CHANNEL_WHITEPAPER = 9; CHANNEL_BOOK_OUTLINE = 10; CHANNEL_WEBINAR = 11; CHANNEL_COURSE = 12; CHANNEL_PODCAST = 13; } enum ContentStatus { CONTENT_STATUS_UNSPECIFIED = 0; CONTENT_STATUS_DRAFT = 1; CONTENT_STATUS_PENDING_REVIEW = 2; CONTENT_STATUS_APPROVED = 3; CONTENT_STATUS_REJECTED = 4; CONTENT_STATUS_PUBLISHED = 5; CONTENT_STATUS_ARCHIVED = 6; } enum CampaignStatus { CAMPAIGN_STATUS_UNSPECIFIED = 0; CAMPAIGN_STATUS_DRAFT = 1; CAMPAIGN_STATUS_ACTIVE = 2; CAMPAIGN_STATUS_PAUSED = 3; CAMPAIGN_STATUS_COMPLETED = 4; CAMPAIGN_STATUS_ARCHIVED = 5; } enum TaskStatus { TASK_STATUS_UNSPECIFIED = 0; TASK_STATUS_TODO = 1; TASK_STATUS_IN_PROGRESS = 2; TASK_STATUS_DONE = 3; TASK_STATUS_SKIPPED = 4; TASK_STATUS_BLOCKED = 5; } enum IntegrationStatus { INTEGRATION_STATUS_UNSPECIFIED = 0; INTEGRATION_STATUS_DISCONNECTED = 1; INTEGRATION_STATUS_CONNECTED = 2; INTEGRATION_STATUS_ERROR = 3; INTEGRATION_STATUS_PENDING = 4; } message StreamChunk { string text = 1; bool is_final = 2; string section = 3; // semantic section marker (e.g. "positioning", "swot", "prescription") float progress = 4; // 0.0 - 1.0 map<string, string> metadata = 5; repeated string agent_tasks = 6; } message DateRange { google.protobuf.Timestamp start = 1; google.protobuf.Timestamp end = 2; } message KeyValue { string key = 1; string value = 2; } message MetricPoint { google.protobuf.Timestamp timestamp = 1; double value = 2; string label = 3; }
